    def delete(self, attachment_id=None):
        if attachment_id is None:
            error_str = 'ERROR: Ticket app and ticket # pair or attachment id required'
            print(error_str)
            print(error_str)
            sys.exit(exit_codes['INPUT_ERROR'])

        attachments = []
        if attachment_id is not None:
            attachments = [attachment_id]
        else:
            ret = self.caps_conn.get_ticket(ticketapp, ticket)
            if (ret):
                # Captured error
                self.caps_conn.dump_debug()
                error_str = 'Error: Failed to fetch attachments.'
                print(error_str)
                print(error_str)
                sys.exit(exit_codes['ATTACHMENT_FETCH_FAILURE'])

            for attachment in self.caps_conn.http_json:
                if (attachment['retention_days'] is None or attachment[
                        'retention_days'] > 1):  # TODO: Change this test to > 0 once CAPS-471 is resolved
                    # Prepare to delete this attachment
                    attachments.append(attachment['id'])
                else:
                    # Attachment already deleted or set to delete
                    warning_str = 'WARNING: Attachment ' + attachment[
                        'id'] + ' is already set for deletion. No action taken.'
                    print(warning_str)
                    print(warning_str)

        if (len(attachments) == 0):
            self.caps_conn.dump_debug()
            warning_str = 'WARNING: No attachments to delete.'
            print(warning_str)
            print(warning_str)
            sys.exit(exit_codes['NO_ATTACHMENTS'])

        # Use err as a flag for a captured error as we iterate through the list of attachments.
        # We will delete as many of the attachments as we can, log any errors, and exit with errors later.
        # err = 0
        for attachment in attachments:
            ret = self.caps_conn.delete_attachment(attachment)
            if ret == 0:
                print('Attachment deleted: ' + attachment)
            else:
                # Failure
                self.caps_conn.dump_debug()
                error_str = 'Error: Attachment ' + attachment + ' failed to delete.'
                print(error_str)
                print(error_str)
                # err = 1

