    def renewtokens(self, tokens):
        sharedsecretlength = 8
        # CAPS interface setup
        try:
            shared_secret = tokens.split(':')[2]
        except IndexError:
            print('\n')
            error_str = 'Error: CAPSV shared secret key not configured in cert file. ' \
                        'Please provide cert file content in format <access key>:<secret key>:<shared secret>'
            print(error_str)
            print('\n')

        if len(shared_secret) != sharedsecretlength:
            print("Shared Secret should be of length " + str(sharedsecretlength))
            sys.exit(exit_codes['INVALID_TOKEN'])
        encryptedsharedsecret = self.encrypt(4 * shared_secret)
        renew_tokens_res = self.caps_conn.renew_tokens(encryptedsharedsecret)
        if renew_tokens_res == 0:
            print('\n')
            print(
                'User Tokens successfully renewed. Please check your email for the new keys')
            print('\n')
        else:
            print('\n')
            print('Unable to renew tokens. Please contact CAPS Support')
            print('\n')

    def encrypt(self, inputstring):
        byte_array = access_key.encode("UTF-8")
        padded = pad(byte_array)
        iv = os.urandom(AES.block_size)
        cipher = AES.new(inputstring.encode("UTF-8"), AES.MODE_CBC, iv)
        encrypted = cipher.encrypt(padded)
        return urllib.parse.quote(base64.b64encode(iv + encrypted).decode("UTF-8"))


